import 'package:flutter/widgets.dart';

import 'gen/app_localizations.dart';

export 'gen/app_localizations.dart';

/// Every player-facing UI string comes from [AppLocalizations]
/// (`lib/l10n/app_<language>.arb`, generated by `flutter gen-l10n`); puzzle
/// content from [ContentText]. English is the template and the fallback.

/// English, for code without a widget tree (tests, defaults).
final AppLocalizations englishStrings = lookupAppLocalizations(const Locale('en'));

/// The strings of [language] (`en`, `tr`).
AppLocalizations stringsFor(String language) => lookupAppLocalizations(Locale(language));

extension L10nContext on BuildContext {
  /// The UI strings here; English when no localization delegate is installed
  /// (bare widget-test harnesses).
  AppLocalizations get l10n =>
      Localizations.of<AppLocalizations>(this, AppLocalizations) ?? englishStrings;
}

extension L10nCase on AppLocalizations {
  /// [text] in capitals, the way this language writes them: Turkish `i`
  /// becomes `İ` (Dart's `toUpperCase` would give `I`: "Gelgit" → "GELGIT").
  String upper(String text) => (localeName.startsWith('tr') ? text.replaceAll('i', 'İ') : text).toUpperCase();
}
